</div><div class="system-form-actions"><a class="system-btn soft" href="<?= legacy_base_url('admin/dashboard.php'); ?>">Batal</a><button class="system-btn primary"><i class="bi bi-save"></i> Simpan Pengaturan Marketplace</button></div></form>
</main>
<script>
(()=>{
const themePrimary=document.getElementById('themePrimary'),themeSecondary=document.getElementById('themeSecondary'),themeAccent=document.getElementById('themeAccent'),themePreview=document.getElementById('themePreview');
function syncThemePreview(){if(!themePreview)return;themePreview.style.setProperty('--preview-primary',themePrimary?.value||'#7C3AED');themePreview.style.setProperty('--preview-secondary',themeSecondary?.value||'#5B21B6');themePreview.style.setProperty('--preview-accent',themeAccent?.value||'#A855F7');const a=document.getElementById('themePrimaryHex'),b=document.getElementById('themeSecondaryHex'),c=document.getElementById('themeAccentHex');if(a)a.textContent=(themePrimary?.value||'').toUpperCase();if(b)b.textContent=(themeSecondary?.value||'').toUpperCase();if(c)c.textContent=(themeAccent?.value||'').toUpperCase();}
document.querySelectorAll('input[name="marketplace_theme_preset"]').forEach(r=>r.addEventListener('change',()=>{if(!r.checked)return;if(r.value!=='custom'){themePrimary.value=r.dataset.primary;themeSecondary.value=r.dataset.secondary;themeAccent.value=r.dataset.accent;}syncThemePreview();}));
[themePrimary,themeSecondary,themeAccent].forEach(el=>el?.addEventListener('input',()=>{const custom=document.getElementById('theme_custom');if(custom)custom.checked=true;syncThemePreview();}));syncThemePreview();
const api='<?= e(legacy_base_url('admin/marketplace-settings/location-options.php')); ?>', resolve='<?= e(legacy_base_url('admin/marketplace-settings/resolve-origin.php')); ?>';
const $=id=>document.getElementById(id); const p=$('originProvince'),c=$('originCity'),d=$('originDistrict'),s=$('originSubdistrict'),status=$('originStatus');
const escapeHtml=x=>String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
function opt(select,label){select.innerHTML='<option value="0">'+escapeHtml(label)+'</option>';select.disabled=true}
async function apiPost(url,payload){const body=new URLSearchParams(payload||{});body.set('_csrf_token','<?= e(CSRF::token()); ?>');const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded','Accept':'application/json'},body});let j={};try{j=await r.json()}catch(_){throw new Error('Response server tidak valid.')}if(!r.ok||!j.success)throw new Error(j.message||'Request gagal');return j;}
async function load(level,parent,select,label,selected){const key=$('rajaApiKey').value.trim();if(!key){select.innerHTML='<option value="0">Masukkan API Key terlebih dahulu</option>';select.disabled=false;status.className='mp-region-status';status.textContent='Masukkan API Key RajaOngkir lalu klik Muat Wilayah.';return false;}select.disabled=true;select.innerHTML='<option>Memuat...</option>';try{const j=await apiPost(api,{level:level,parent_id:parent||0,api_key:key});const rows=Array.isArray(j.data)?j.data:[];select.innerHTML='<option value="0">'+escapeHtml(label)+'</option>'+rows.map(x=>'<option value="'+x.id+'" data-name="'+escapeHtml(x.name)+'" data-zip="'+escapeHtml(x.zip_code||'')+'" '+(String(x.id)===String(selected)?'selected':'')+'>'+escapeHtml(x.name)+(x.zip_code&&x.zip_code!=='0'?' ('+escapeHtml(x.zip_code)+')':'')+'</option>').join('');select.disabled=false;status.className='mp-region-status ok';status.textContent=rows.length?'Wilayah berhasil dimuat. Pilih Provinsi lalu lanjutkan sampai Kelurahan/Desa.':'API terhubung, tetapi daftar wilayah kosong.';return true;}catch(e){select.innerHTML='<option value="0">Gagal memuat wilayah</option>';select.disabled=false;status.className='mp-region-status';status.textContent=e.message||'Gagal memuat wilayah';return false;}}
function sync(sel,id,name){const o=sel.options[sel.selectedIndex];$(id).value=sel.value||'0';$(name).value=o?.dataset?.name||((sel.value&&sel.value!=='0')?o?.textContent:'')||'';}
async function resolveOrigin(){sync(s,'originSubdistrictId','originSubdistrictName');$('originZip').value=s.options[s.selectedIndex]?.dataset?.zip||'';$('originDirectId').value='0';$('originLabel').value='';if(!s.value||s.value==='0'){status.className='mp-region-status';status.textContent='Pilih Kelurahan/Desa.';return;}status.className='mp-region-status';status.textContent='Memetakan ID ongkir...';try{const j=await apiPost(resolve,{subdistrict:$('originSubdistrictName').value,district:$('originDistrictName').value,city:$('originCityName').value,zip_code:$('originZip').value,api_key:$('rajaApiKey').value.trim()});$('originDirectId').value=j.data.id||0;$('originLabel').value=j.data.label||'';$('originZip').value=j.data.zip_code||$('originZip').value;status.className='mp-region-status ok';status.textContent='Lokasi asal aktif: '+(j.data.label||'');}catch(e){status.className='mp-region-status';status.textContent=e.message||'Gagal memetakan wilayah';}}
p.addEventListener('change',()=>{sync(p,'originProvinceId','originProvinceName');opt(c,'Pilih Kota/Kabupaten');opt(d,'Pilih Kecamatan');opt(s,'Pilih Kelurahan/Desa');$('originDirectId').value='0';if(+p.value>0)load('city',p.value,c,'Pilih Kota/Kabupaten',0)});
c.addEventListener('change',()=>{sync(c,'originCityId','originCityName');opt(d,'Pilih Kecamatan');opt(s,'Pilih Kelurahan/Desa');$('originDirectId').value='0';if(+c.value>0)load('district',c.value,d,'Pilih Kecamatan',0)});
d.addEventListener('change',()=>{sync(d,'originDistrictId','originDistrictName');opt(s,'Pilih Kelurahan/Desa');$('originDirectId').value='0';if(+d.value>0)load('subdistrict',d.value,s,'Pilih Kelurahan/Desa',0)});
s.addEventListener('change',resolveOrigin);
async function loadSavedRegionChain(){const sp=$('originProvinceId').value,sc=$('originCityId').value,sd=$('originDistrictId').value,ss=$('originSubdistrictId').value;const ok=await load('province',0,p,'Pilih Provinsi',sp);if(!ok)return;if(+sp>0)await load('city',sp,c,'Pilih Kota/Kabupaten',sc);if(+sc>0)await load('district',sc,d,'Pilih Kecamatan',sd);if(+sd>0)await load('subdistrict',sd,s,'Pilih Kelurahan/Desa',ss);}
$('loadRajaRegions')?.addEventListener('click',async()=>{status.className='mp-region-status';status.textContent='Menghubungkan ke RajaOngkir...';await loadSavedRegionChain();});
$('rajaApiKey')?.addEventListener('change',()=>{if($('rajaApiKey').value.trim()){loadSavedRegionChain();}else{opt(p,'Pilih Provinsi');opt(c,'Pilih Kota/Kabupaten');opt(d,'Pilih Kecamatan');opt(s,'Pilih Kelurahan/Desa');p.disabled=false;status.className='mp-region-status';status.textContent='Masukkan API Key RajaOngkir lalu klik Muat Wilayah.';}});
if($('rajaApiKey').value.trim()) loadSavedRegionChain();
const waStatus=$('waStatus'), waDevice=$('waDevice'), waName=$('waDeviceName');
async function waPost(url,payload){const body=new URLSearchParams(payload);body.set('_csrf_token','<?= e(CSRF::token()); ?>');const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded','Accept':'application/json'},body});const j=await r.json();if(!r.ok||!j.success)throw new Error(j.message||'Request gagal');return j;}
$('loadWaDevices')?.addEventListener('click',async()=>{waStatus.textContent='Memuat device...';try{const j=await waPost('<?= e($waDevicesUrl); ?>',{api_token:$('waApiToken').value});waDevice.innerHTML='<option value="0">Pilih device</option>'+j.data.map(x=>'<option value="'+x.id+'" data-name="'+escapeHtml(x.name)+'">'+escapeHtml(x.name)+' • '+escapeHtml(x.phone_number||'-')+' • '+escapeHtml(x.status)+'</option>').join('');const saved='<?= (int)$v('marketplace_wa_device_id','0'); ?>';if(saved)waDevice.value=saved;waStatus.className='mp-region-status ok';waStatus.textContent='Device berhasil dimuat: '+j.data.length;}catch(e){waStatus.className='mp-region-status';waStatus.textContent=e.message;}});
waDevice?.addEventListener('change',()=>{const o=waDevice.options[waDevice.selectedIndex];waName.value=o?.dataset?.name||'';});
$('testWaBtn')?.addEventListener('click',async()=>{waStatus.textContent='Mengirim pesan tes...';try{const j=await waPost('<?= e($waTestUrl); ?>',{api_token:$('waApiToken').value,device_id:waDevice.value,recipient:$('waTestPhone').value});waStatus.className='mp-region-status ok';waStatus.textContent=j.message||'Pesan tes berhasil dikirim.';}catch(e){waStatus.className='mp-region-status';waStatus.textContent=e.message;}});
document.querySelectorAll('[data-copy]').forEach(btn=>btn.addEventListener('click',async()=>{const el=document.querySelector(btn.dataset.copy);if(!el)return;try{await navigator.clipboard.writeText(el.value);btn.textContent='Tersalin';setTimeout(()=>btn.textContent='Salin',1400)}catch(_){el.select();document.execCommand('copy')}}));
})();
</script>
